package org.apache.commons.lang.time;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Calendar;
import java.util.Date;
import java.util.TimeZone;
import org.apache.commons.lang.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class DurationFormatUtils_formatPeriod_TriageGen2Test {

    private static final TimeZone GMT = TimeZone.getTimeZone("GMT");
    private static final TimeZone EST = TimeZone.getTimeZone("EST");

    @Test
    public void testFormatPeriod_ShortDuration_UsesFormatDuration() {
        // Less than 28 days
        long start = 1000L;
        long end = 2000L;
        // Should call formatDuration internally
        String result = DurationFormatUtils.formatPeriod(start, end, "s", false, GMT);
        assertEquals("1", result);
    }

    @Test
    public void testFormatPeriod_LongDuration_YearsMonthsDays() {
        // Testing the logic that handles Year, Month, Day tokens
        // Jan 1, 2020 to Jan 1, 2022 (2 years)
        Calendar cal = Calendar.getInstance(GMT);
        cal.set(2020, Calendar.JANUARY, 1, 0, 0, 0);
        cal.set(Calendar.MILLISECOND, 0);
        long start = cal.getTimeInMillis();

        cal.set(2022, Calendar.JANUARY, 1, 0, 0, 0);
        cal.set(Calendar.MILLISECOND, 0);
        long end = cal.getTimeInMillis();

        String result = DurationFormatUtils.formatPeriod(start, end, "y 'years' M 'months' d 'days'", false, GMT);
        // Note: Exact result depends on how reduceAndCorrect/lexx handles the logic, 
        // but we test the branch coverage for the year/month logic.
        // Based on code: if Y is present but M is not, days += 365 * years.
        // Since we provided M, it does months += 12 * years.
        assertEquals("2 years 0 months 0 days", result);
    }

    @Test
    public void testFormatPeriod_NoYearsToken_ConvertsYearsToMonths() {
        // Test: if (!Token.containsTokenWithValue(y)) { if (Token.containsTokenWithValue(M)) ... }
        Calendar cal = Calendar.getInstance(GMT);
        cal.set(2020, Calendar.JANUARY, 1, 0, 0, 0);
        cal.set(Calendar.MILLISECOND, 0);
        long start = cal.getTimeInMillis();

        cal.set(2021, Calendar.JANUARY, 1, 0, 0, 0);
        cal.set(Calendar.MILLISECOND, 0);
        long end = cal.getTimeInMillis();

        // Format only has M and d. Year is not in format.
        // Logic should convert 1 year into 12 months.
        String result = DurationFormatUtils.formatPeriod(start, end, "M 'months' d 'days'", false, GMT);
        assertEquals("12 months 0 days", result);
    }

    @Test
    public void testFormatPeriod_NoYearsNoMonths_ConvertsYearsToDays() {
        // Test: if (!Token.containsTokenWithValue(y)) { if (!Token.containsTokenWithValue(M)) ... }
        Calendar cal = Calendar.getInstance(GMT);
        cal.set(2020, Calendar.JANUARY, 1, 0, 0, 0);
        cal.set(Calendar.MILLISECOND, 0);
        long start = cal.getTimeInMillis();

        cal.set(2021, Calendar.JANUARY, 1, 0, 0, 0);
        cal.set(Calendar.MILLISECOND, 0);
        long end = cal.getTimeInMillis();

        // Format only has d. Year and Month are not in format.
        // Logic should convert 1 year into 365 days.
        String result = DurationFormatUtils.formatPeriod(start, end, "d 'days'", false, GMT);
        assertEquals("365 days", result);
    }

    @Test
    public void testFormatPeriod_NoMonthsToken_ConvertsMonthsToDays() {
        // Test: if (!Token.containsTokenWithValue(M)) { days += end.get(DAY_OF_YEAR) - start.get(DAY_OF_YEAR); months = 0; }
        Calendar cal = Calendar.getInstance(GMT);
        cal.set(2020, Calendar.JANUARY, 1, 0, 0, 0);
        cal.set(Calendar.MILLISECOND, 0);
        long start = cal.getTimeInMillis();

        cal.set(2020, Calendar.MARCH, 1, 0, 0, 0);
        cal.set(Calendar.MILLISECOND, 0);
        long end = cal.getTimeInMillis();

        // Format only has d. Month is not in format.
        String result = DurationFormatUtils.formatPeriod(start, end, "d 'days'", false, GMT);
        // 2020 is a leap year. Jan(31) + Feb(29) = 60 days difference in day of year? 
        // Actually, it checks DAY_OF_YEAR. Jan 1 is 1, March 1 is 61. 61-1 = 60.
        // Plus the initial 'days' calculation.
        // This test ensures the branch for !Token.containsTokenWithValue(M) is hit.
        // We check if the result is a string containing days.
        assert(result.contains("days"));
    }

    @Test
    public void testFormatPeriod_NegativeRollup_SecondsMinutesHours() {
        // Trigger the while (seconds < 0) etc. logic
        // By setting end time to be slightly "before" start time in terms of components
        // e.g., Start at 10:00:50, End at 11:00:10
        Calendar cal = Calendar.getInstance(GMT);
        cal.set(2020, Calendar.JANUARY, 1, 10, 0, 50);
        cal.set(Calendar.MILLISECOND, 0);
        long start = cal.getTimeInMillis();

        cal.set(2020, Calendar.JANUARY, 1, 11, 0, 10);
        cal.set(Calendar.MILLISECOND, 0);
        long end = cal.getTimeInMillis();

        // Duration is 20 seconds (less than 28 days), so it hits formatDuration.
        // To hit the complex logic, we must exceed 28 days.
        cal.add(Calendar.DAY_OF_MONTH, 30);
        end = cal.getTimeInMillis();

        // Now it enters the long duration logic.
        // The difference in seconds is 10 - 50 = -40.
        // The while (seconds < 0) loop will run.
        String result = DurationFormatUtils.formatPeriod(start, end, "m 'm' s 's'", false, GMT);
        // We don't check exact value because reduceAndCorrect is internal, 
        // but we ensure it doesn't crash and executes the negative adjustment branches.
        assert(result != null);
    }

    @Test
    public void testFormatPeriod_TimezoneImpact() {
        // Test that timezone is actually used in Calendar instantiation
        Calendar cal = Calendar.getInstance(EST);
        cal.set(2020, Calendar.JANUARY, 1, 12, 0, 0);
        cal.set(Calendar.MILLISECOND, 0);
        long start = cal.getTimeInMillis();

        cal.add(Calendar.DAY_OF_MONTH, 30);
        long end = cal.getTimeInMillis();

        // Test with EST
        String resultEST = DurationFormatUtils.formatPeriod(start, end, "d 'days'", false, EST);
        // Test with GMT
        String resultGMT = DurationFormatUtils.formatPeriod(start, end, "d 'days'", false, GMT);

        // If timezone matters for the day calculation (e.g. crossing midnight), 
        // results might differ.
        assert(resultEST != null);
        assert(resultGMT != null);
    }

    @Test
    public void testFormatPeriod_Padding() {
        // Test padWithZeros = true
        Calendar cal = Calendar.getInstance(GMT);
        cal.set(2020, Calendar.JANUARY, 1, 0, 0, 0);
        cal.set(Calendar.MILLISECOND, 0);
        long start = cal.getTimeInMillis();

        cal.add(Calendar.DAY_OF_MONTH, 30);
        cal.add(Calendar.HOUR_OF_DAY, 1);
        cal.add(Calendar.MINUTE, 1);
        long end = cal.getTimeInMillis();

        String result = DurationFormatUtils.formatPeriod(start, end, "H 'h' m 'm'", true, GMT);
        // Expecting 01h 01m or similar depending on lexx/format implementation
        assert(result.contains("01"));
    }
}
